import openpyxl, re
p='/tmp/llm_rollout_8fub19et/seed_collection_0076_relative_vs_absolute_references_6733_input.xlsx'
wb=openpyxl.load_workbook(p, data_only=False)
ws=wb['simplecorr']
anoms=[]
for row in ws.iter_rows():
    for c in row:
        if c.data_type=='f' or (isinstance(c.value,str) and c.value.startswith('=')):
            f=c.value
            # extract first arg after CORREL(
            m=re.match(r'=CORREL\((.*?),(.*?)\)$', f)
            if m:
                arg1=m.group(1).strip()
                if not (arg1.startswith('$C$') and arg1.endswith('$228')):
                    anoms.append((c.coordinate,f,arg1))
print('anoms', anoms)
# also list all arg1 forms
forms=set()
for row in ws.iter_rows():
    for c in row:
        if c.data_type=='f' or (isinstance(c.value,str) and c.value.startswith('=')):
            f=c.value
            m=re.match(r'=CORREL\((.*?),(.*?)\)$', f)
            if m:
                forms.add(m.group(1).strip())
print('arg1 forms', sorted(forms))
# arg2 forms
forms2=set()
for row in ws.iter_rows():
    for c in row:
        if c.data_type=='f' or (isinstance(c.value,str) and c.value.startswith('=')):
            f=c.value
            m=re.match(r'=CORREL\((.*?),(.*?)\)$', f)
            if m:
                forms2.add(m.group(2).strip())
print('arg2 forms count', len(forms2))
print(sorted(forms2)[:5], sorted(forms2)[-5:])
